
import type { MerchantAccountSessionEffectivePolicy } from './MerchantAccountSessionEffectivePolicy.js';
import type { MerchantAccountSessionStripeComponent } from './MerchantAccountSessionStripeComponent.js';
import type { OnboardingRequirements } from './OnboardingRequirements.js';

export type MerchantAccountSession = { /** Browser initialization data required to mount embedded account-management components. These instructions are not merchant account resource state. */ "client_session": { /** Expiry of the embedded account session client secret in UTC. Connect.js calls fetchClientSecret to obtain a new secret when needed. Format: date-time. */ "expires_at": string; /** Stripe Connect initialization credentials and authorized component collection options. Connect initializes from the account session client secret and does not take a connected account ID. */ "stripe": { /** Account session authority for initializing Stripe Connect in the browser. */ "account_session": { /** Short-lived account session client secret to return from fetchClientSecret. Return it only to an authenticated human authorized to manage this merchant. */ "client_secret": string; /** Browser initialization operation to perform. load_connect_and_initialize means call loadConnectAndInitialize with publishableKey and fetchClientSecret. */ "stripe_js_call": "load_connect_and_initialize" | (string & {}); }; /** Authorized Stripe component names and collection options to apply when mounting each component. */ "components": Array<MerchantAccountSessionStripeComponent>; /** Stripe publishable key to pass as publishableKey to loadConnectAndInitialize. */ "publishable_key": string; }; }; /** minItems: 1. */ "components": Array<"account_onboarding" | "account_management" | "payouts" | "balances" | "tax_documents" | "notification_banner" | (string & {})>; "effective_policy": MerchantAccountSessionEffectivePolicy; /** Signed Flint token to exchange at POST /v1/merchant-account-sessions/refresh. Each successful refresh rotates this token. The caller must still authenticate and authorize the human using the session. */ "launch_token": string; /** Expiry of launch_token in UTC. After expiry, create a new merchant account session. Format: date-time. */ "launch_token_expires_at": string; "requirements": OnboardingRequirements; };
